solution:
interface Validable {
    boolean validar();
}

abstract class Pago {
    double monto;
    Pago(double monto) { this.monto = monto; }
    abstract void procesar();
}

class PagoTarjeta extends Pago implements Validable {
    String numero;
    PagoTarjeta(double monto, String numero) { super(monto); this.numero = numero; }
    @Override public boolean validar() { return numero.length() == 16; }
    @Override void procesar() {
        String ultimas = numero.substring(numero.length() - 4);
        System.out.println("TC ****" + ultimas + " - $" + monto);
    }
}

class PagoEfectivo extends Pago implements Validable {
    PagoEfectivo(double monto) { super(monto); }
    @Override public boolean validar() { return monto > 0 && monto <= 500; }
    @Override void procesar() { System.out.println("Cash: $" + monto); }
}

public class Main {
    static void cobrar(Pago p) {
        if (p instanceof Validable && !((Validable) p).validar()) {
            System.out.println("Invalid payment");
            return;
        }
        p.procesar();
    }
    public static void main(String[] args) {
        cobrar(new PagoTarjeta(150, "1234567812345678"));
        cobrar(new PagoEfectivo(300));
        cobrar(new PagoEfectivo(600));
    }
}
